<template><AppShell><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else><view class="detail-crumb"><button class="text-button" @tap="go('person',{id})">← {{personName}}档案</button></view><view class="page-heading sources-cover"><text class="eyebrow">引用可追溯 / SOURCES</text><text class="page-title">让每一段阅读，有据可循</text><text class="muted">先看资料支持什么，再看作者、定位和访问记录。</text></view><view class="list-summary"><text>{{sources.length}} 份阅读来源</text></view><view class="sources-grid"><view v-for="(s,i) in sources" :key="s.id" class="source-card"><view class="source-card-top"><text class="source-number">{{String(i+1).padStart(2,'0')}}</text></view><text class="source-title">{{s.title}}</text><text class="muted">{{s.publisher}}</text><view class="source-card-loc"><text class="eyebrow">引用定位</text><text>{{s.location}}</text></view><button class="text-button" @tap="sourceId=s.id">查看记载与来源详情 ↗</button></view></view><StatePanel v-if="!sources.length" title="来源还在整理" message="暂无可以公开阅读的来源条目。"/></template><SourceSheet :source-id="sourceId" @close="sourceId=''"/></AppShell></template>
<script setup>
import {ref} from 'vue';import {onLoad,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import SourceSheet from '../../components/SourceSheet.vue';import {api} from '../../lib/api.js';import {go} from '../../lib/navigation.js'
const sources=ref([]),personName=ref('人物'),loading=ref(true),error=ref(''),sourceId=ref('');let id='P009'
async function load(){loading.value=true;error.value='';try{const [s,p]=await Promise.all([api('people/'+id+'/sources'),api('people/'+id)]);sources.value=s.items;personName.value=p.name}catch(e){error.value=e.message}finally{loading.value=false}}
onLoad(options=>{id=options.id||'P009';load()});onShareAppMessage(()=>({title:personName.value+' · 事实与来源',path:'/pages/sources/index?id='+id}))
</script>
